const $=s=>document.querySelector(s),KEY='eq-mnemonics-v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let cards=[],progress={},custom={},page=0,order=null;const SIZE=12;const revealed=new Set();
try{const saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(saved&&typeof saved==='object'){progress=saved.progress||{};custom=saved.custom||{};}}catch{$('#notice').textContent='無法讀取舊進度，仍可使用字卡。';}
const player=new Audio();player.preload='none';let active=null;
function stop(){player.pause();active=null;document.querySelectorAll('[data-play]').forEach(b=>{b.textContent='▶ 英文 MP3';b.setAttribute('aria-pressed','false');});}
player.addEventListener('ended',stop);player.addEventListener('error',()=>{stop();$('#notice').textContent='MP3 無法載入，請重試或下載音檔。';});
function save(){try{localStorage.setItem(KEY,JSON.stringify({version:1,progress,custom}));}catch{$('#notice').textContent='無法儲存到此瀏覽器；請匯出備份。';}}
function list(){const query=$('#search').value.trim().toLowerCase(),category=$('#category').value,kind=$('#kind').value,mode=$('#review').value;let result=cards.filter(c=>(!query||[c.word,c.zh,c.cue,custom[c.id],c.scene].join(' ').toLowerCase().includes(query))&&(!category||c.category===category)&&(!kind||c.origin===kind)&&(mode==='all'||(mode==='new'?!progress[c.id]:Number(progress[c.id]?.due)<=Date.now())));if(order){const rank=new Map(order.map((id,i)=>[id,i]));result.sort((a,b)=>rank.get(a.id)-rank.get(b.id));}return result;}
function render(){stop();const filtered=list();page=Math.max(0,Math.min(page,Math.ceil(filtered.length/SIZE)-1));$('#count').textContent=`${filtered.length.toLocaleString()} / 1,000 字 · 已練習 ${cards.filter(c=>progress[c.id]).length} 字`;
$('#cards').innerHTML=filtered.slice(page*SIZE,(page+1)*SIZE).map(c=>{const open=revealed.has(c.id),saved=progress[c.id],cue=custom[c.id]||c.cue;return `<article class="word-card" data-id="${esc(c.id)}"><div class="topline"><span>${esc(c.category)}</span><span>${esc(c.kind)}</span></div><div class="icon" role="img" aria-label="${esc(c.zh)}圖示">${esc(c.icon)}</div><h2 lang="en">${esc(c.word)}</h2><p class="phonetic" lang="en">音素：${esc(c.sounds)}</p><div class="actions"><button class="play" data-play="${esc(c.id)}" aria-label="播放 ${esc(c.word)} 英文 MP3" aria-pressed="false">▶ 英文 MP3</button><a class="download" href="audio/${encodeURIComponent(c.word)}.mp3" download="${esc(c.word)}.mp3" aria-label="下載 ${esc(c.word)} MP3">↓ MP3</a></div><button data-reveal="${esc(c.id)}" aria-expanded="${open}" aria-controls="answer-${esc(c.id)}">${open?'遮住答案，再回想':'翻卡：看意思與諧音'}</button><div class="answer" id="answer-${esc(c.id)}" ${open?'':'hidden'}><p class="meaning">${esc(c.zh)}</p><p class="cue">${esc(cue)}</p><p class="scene">${esc(custom[c.id]?'用自己的口訣連結這個字的意思，再跟著 MP3 念一次。':c.scene)}</p>${c.word==='ambulance'?'<p lang="en">The ambulance takes the patient to the hospital.</p><p>救護車將病人送到醫院。</p>':''}<p class="status">${'近似聲音聯想・請以 MP3 核對發音'}</p>${c.soundNote?`<p class="sound-note">辨音：${esc(c.soundNote)}</p>`:""}<div class="grade"><button data-grade="${esc(c.id)}" data-correct="false">還沒記住</button><button data-grade="${esc(c.id)}" data-correct="true">回想答對了</button></div><details class="custom"><summary>寫我的諧音口訣</summary><label for="custom-${esc(c.id)}">口訣（最多 200 字）</label><textarea id="custom-${esc(c.id)}" maxlength="200">${esc(custom[c.id]||'')}</textarea><button data-save="${esc(c.id)}">儲存口訣</button><button data-reset="${esc(c.id)}">恢復原口訣</button></details></div><p class="status">${saved?`已練習 ${Number(saved.reviews)||0} 次 · 下次 ${new Date(saved.due).toLocaleString('zh-TW')}`:'尚未練習'}</p></article>`;}).join('')||'<p>沒有符合條件的字卡。可清除搜尋或切換篩選。</p>';
$('#prev').disabled=page===0;$('#next').disabled=(page+1)*SIZE>=filtered.length;$('#page').textContent=`${filtered.length?page+1:0} / ${Math.ceil(filtered.length/SIZE)} 頁`;
}
$('#cards').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const d=b.dataset,id=d.play||d.reveal||d.grade||d.save||d.reset,c=cards.find(c=>c.id===id);if(!c)return;
if(d.play){if(active===id&&!player.paused){stop();return;}stop();active=id;player.src=new URL('audio/'+encodeURIComponent(c.word)+'.mp3',import.meta.url).href;try{await player.play();if(active===id){b.textContent='Ⅱ 暫停';b.setAttribute('aria-pressed','true');}}catch{stop();$('#notice').textContent='無法開始播放，請重試或使用 MP3 下載。';}return;}
if(d.reveal){revealed.has(id)?revealed.delete(id):revealed.add(id);const answer=$('#answer-'+id);answer.hidden=!revealed.has(id);b.setAttribute('aria-expanded',String(!answer.hidden));b.textContent=answer.hidden?'翻卡：看意思與諧音':'遮住答案，再回想';return;}
if(d.grade){const ok=d.correct==='true',old=progress[id],step=ok?Math.min((Number(old?.step)||0)+1,4):0;progress[id]={step,reviews:(Number(old?.reviews)||0)+1,due:Date.now()+(ok?[0,1,3,7,14][step]*86400000:600000)};save();revealed.delete(id);render();$('#notice').textContent=`${c.word} 已記錄；${ok?'依進度安排下次複習。':'十分鐘後再試一次。'}`;}
if(d.save){const value=$('#custom-'+id).value.trim();if(value)custom[id]=value.slice(0,200);else delete custom[id];save();render();$('#notice').textContent='口訣已儲存。';}
if(d.reset){delete custom[id];save();render();$('#notice').textContent='已恢復原口訣。';}
});
for(const id of ['search','category','kind','review'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=0;render();});
for(const [id,delta]of [['prev',-1],['next',1]])$('#'+id).addEventListener('click',()=>{page+=delta;render();$('#cards').scrollIntoView({block:'start'});$('#cards h2')?.setAttribute('tabindex','-1');$('#cards h2')?.focus({preventScroll:true});});
$('#shuffle').addEventListener('click',()=>{order=cards.map(c=>c.id);for(let i=order.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[order[i],order[j]]=[order[j],order[i]];}page=0;render();});
$('#export').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({version:1,progress,custom},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='english-quest-mnemonics-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
$('#import').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw Error();const data=JSON.parse(await file.text());if(data.version!==1||!data.progress||!data.custom)throw Error();const ids=new Set(cards.map(c=>c.id));for(const [id,value]of Object.entries(data.custom)){if(ids.has(id)&&typeof value==='string')custom[id]=value.slice(0,200);}for(const [id,value]of Object.entries(data.progress)){if(ids.has(id)&&Number.isFinite(value?.due)&&Number.isInteger(value.reviews)&&value.reviews>=0&&Number.isInteger(value.step)&&value.step>=0&&value.step<=4)progress[id]={due:value.due,reviews:value.reviews,step:value.step};}save();render();$('#notice').textContent='已合併匯入備份。';}catch{$('#notice').textContent='無法匯入；請選擇本頁匯出的 JSON 備份。';}e.target.value='';});
window.addEventListener('pagehide',stop);
try{const r=await fetch(new URL('cards.json',import.meta.url));if(!r.ok)throw Error();cards=await r.json();if(!Array.isArray(cards)||cards.length!==1000)throw Error();$('#category').innerHTML='<option value="">全部主題</option>'+[...new Set(cards.map(c=>c.category))].map(c=>`<option>${esc(c)}</option>`).join('');$('#editorial').textContent='1,000 張正式聯想已全部編寫完成：原有 67 張、本次補齊 933 張。每字都有專屬口訣、意思場景、圖示及可播放下載的獨立 MP3。';render();}catch{$('#count').textContent='字卡載入失敗，請重新整理再試。';}
